// apps/angular-insurance/scripts/write-akku-env.mjs — turns environment variables into a TypeScript
// module, before `ng` runs.
//
// WHY THIS EXISTS. Vite substitutes `import.meta.env.VITE_*` at build time, which is how the two
// React apps learn which Akku site they point at. Angular has no equivalent: `import.meta.env` is
// not a language feature, and `angular.json` is static JSON that cannot read `process.env`. The
// standard Angular answer is a generated file, so that is what this is.
//
// WHY NOT A LITERAL IN THE SOURCE. Same reason `consent/config.ts` refuses to default the host: a
// checked-in hostname means a fresh clone with no environment silently talks to one particular
// deployment, which is how somebody writes consent decisions into production believing they are
// local. Absent is honest; the app says it is unconfigured and stops.
//
// PRECEDENCE: real environment variables win over `.env.local`. On Vercel there is no `.env.local`
// and the project's variables are the only source; on a laptop the file is the convenient one. Both
// `AKKU_*` and `VITE_AKKU_*` spellings are accepted so the file can be copied straight from
// apps/banking without renaming anything.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const appDir = dirname(dirname(fileURLToPath(import.meta.url)));

/** A deliberately small `.env` reader: `KEY=value`, `#` comments, no interpolation or quoting rules.
 * Anything more elaborate belongs to dotenv, and this file is not worth a dependency. */
function readEnvFile(path) {
  if (!existsSync(path)) return {};
  const out = {};
  for (const line of readFileSync(path, 'utf8').split(/\r?\n/)) {
    const trimmed = line.trim();
    if (trimmed.length === 0 || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    out[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
  }
  return out;
}

const fromFile = readEnvFile(join(appDir, '.env.local'));
const pick = (name) =>
  process.env[`AKKU_${name}`] ??
  process.env[`VITE_AKKU_${name}`] ??
  fromFile[`AKKU_${name}`] ??
  fromFile[`VITE_AKKU_${name}`] ??
  '';

const values = {
  apiHost: pick('API_HOST'),
  siteKey: pick('SITE_KEY'),
  appId: pick('APP_ID'),
};

const target = join(appDir, 'src', 'app', 'core', 'akku-env.generated.ts');
writeFileSync(
  target,
  `// GENERATED by scripts/write-akku-env.mjs. Do not edit, and do not commit — it is gitignored.
// Regenerated before every \`pnpm dev\` and \`pnpm build\`.
export const AKKU_ENV = ${JSON.stringify(values, null, 2)} as const;
`,
  'utf8',
);

const missing = Object.entries(values)
  .filter(([, value]) => value.length === 0)
  .map(([name]) => name);

// A warning, never a failure. Rule #1 says a consent surface is never what breaks an app, and the
// same restraint applies to its build: an unconfigured checkout should still compile and run, and
// say so on screen.
console.log(
  missing.length === 0
    ? `akku env: configured (${values.apiHost})`
    : `akku env: NOT configured — missing ${missing.join(', ')}. The app will run and report itself unconfigured.`,
);
